// Original study paraphrases of the supplied, edited Chapter 13.
// Source IDs refer to nonempty paragraphs in the private DOCX extraction.
// Body bold, not chapter/section headings, defines the fourteen key terms.
export const VERSION='8.5.0';
export const SECTIONS=[
 {id:'13.1',title:'Religion & individualism',summary:'Revival, personal salvation, Emerson, Thoreau and the tension between self-reliance and conformity.'},
 {id:'13.2',title:'Communal experiments',summary:'Religious and secular communities tested alternatives to competition, private property and conventional work.'},
 {id:'13.3',title:'Health & temperance',summary:'Moderation became total abstinence and prohibition; reform also produced the discredited claims of phrenology.'},
 {id:'13.4',title:'Addressing slavery',summary:'Colonization, resistance, immediatism, moral suasion, Black leadership and political abolitionism took different approaches.'},
 {id:'13.5',title:'Women’s rights',summary:'Abolition organizing helped women challenge exclusion and organize the 1848 Seneca Falls Convention.'}
];
export const TERMS=[
 {id:'second-great-awakening',name:'Second Great Awakening',section:'13.1',definition:'A wave of evangelical Protestant revivals emphasizing emotional conversion, personal salvation and the possibility of moral reform.',example:'A traveling minister invites listeners at an outdoor revival to leave sin behind and begin a righteous life.',contrast:'The First Great Awakening belongs to the 1730s–1740s; this later revival helped energize antebellum reform.',source:['P003','P004']},
 {id:'millennialism',name:'millennialism',section:'13.1',definition:'The belief that God’s kingdom would be established on earth for a thousand years of harmony and Christian morality.',example:'A believer works for a morally reformed society in anticipation of a thousand-year divine reign.',contrast:'This is a religious expectation, not simply optimism about economic growth or the year 2000.',source:['P004']},
 {id:'transcendentalism',name:'transcendentalism',section:'13.1',definition:'An intellectual movement emphasizing individual intuition, spiritual insight and nature beyond ordinary sensory experience or social conformity.',example:'A reader of Emerson trusts independent judgment and seeks spiritual meaning in nature.',contrast:'It challenged conformity and excessive reliance on calculating reason; it was not a demand to obey the majority.',source:['P009','P010','P012']},
 {id:'pietistic',name:'pietistic',section:'13.2',definition:'Emphasizing an individual’s transforming religious experience and personal piety over formal ritual.',example:'A German Protestant community places inward spiritual change above elaborate ceremonies.',contrast:'Pietistic describes the emphasis of religious life, not a secular plan based only on human reason.',source:['P018']},
 {id:'shakers',name:'Shakers',section:'13.2',definition:'A religious communal group with roots in English Quakerism that practiced shared property, equality of men and women, and self-sufficient work.',example:'A community shares its goods and values carefully made furniture rather than private luxury.',contrast:'Their communal religious experiment differed from Owen’s secular faith in reason and from private-property competition.',source:['P019']},
 {id:'mormons',name:'Mormons',section:'13.2',definition:'The popular historical name for members of the religious movement Joseph Smith organized in 1830, later led west by Brigham Young.',example:'After Smith’s death, Young leads the community toward a lasting settlement in the Salt Lake region.',contrast:'Joseph Smith founded the movement; Brigham Young led its later migration. They were different leaders.',source:['P020','P021']},
 {id:'temperance',name:'temperance',section:'13.3',definition:'Moderation or self-restraint, especially in alcohol use; early temperance groups urged restrained drinking.',example:'An early society asks people to stop overindulging rather than give up every alcoholic drink.',contrast:'Temperance could mean moderation; teetotalism specifically meant complete abstinence from alcohol.',source:['P027','P029']},
 {id:'teetotalism',name:'teetotalism',section:'13.3',definition:'Total abstinence from alcohol, including beer and wine as well as hard liquor.',example:'A signer pledges to drink no whiskey, rum, beer or wine.',contrast:'Avoiding only hard liquor while continuing to drink wine is not teetotalism.',source:['P029','P031']},
 {id:'phrenology',name:'Phrenology',section:'13.3',definition:'The discredited practice of claiming to read mental qualities or character from the shape and bumps of the skull.',example:'A lecturer examines someone’s skull and claims its contours reveal that person’s abilities.',contrast:'It was popular in the nineteenth century but is now recognized as pseudoscience, not a valid character test.',source:['P035','P036']},
 {id:'colonization',name:'colonization',section:'13.4',definition:'In this chapter, the movement to relocate African Americans outside the United States, usually to Africa.',example:'The American Colonization Society supports relocation to Liberia rather than equality in the United States.',contrast:'Colonization displaced Black people; abolitionists such as Garrison rejected it as racist and demanded an end to slavery.',source:['P039','P040','P047']},
 {id:'abolitionist',name:'abolitionist',section:'13.4',definition:'A person working to end slavery; the chapter emphasizes activists who demanded its immediate elimination and equal rights.',example:'An activist publishes formerly enslaved people’s accounts and organizes antislavery petitions.',contrast:'Opposing slavery’s expansion alone was a narrower position than demanding slavery’s abolition.',source:['P044','P045','P048']},
 {id:'moral-suasion',name:'moral suasion',section:'13.4',definition:'An effort to change behavior by appealing to conscience and persuading people that slavery was morally wrong.',example:'A formerly enslaved speaker describes families being separated to awaken an audience’s conscience.',contrast:'This is a method of persuasion; immediatism names the demand for immediate action to end slavery.',source:['P047','P048']},
 {id:'immediatism',name:'immediatism',section:'13.4',definition:'The moral demand to take immediate action to end slavery rather than postpone emancipation.',example:'An abolitionist insists that an unjust institution must end now rather than through an indefinite gradual plan.',contrast:'It identifies the urgency of abolition; it does not mean every abolitionist supported violent tactics.',source:['P048']},
 {id:'seneca-falls',name:'Seneca Falls',section:'13.5',definition:'The New York location of the 1848 women’s rights convention associated with Lucretia Mott, Elizabeth Cady Stanton and the Declaration of Sentiments.',example:'Reformers adapt the Declaration of Independence’s equality language to demand rights for women.',contrast:'The convention asserted women’s rights; it did not itself give all women the vote.',source:['P057','P059']}
];

const bank=[];
function add(section,kind,prompt,correct,distractors,explanation,source,termId){
 const index=bank.length,answer=index%4,choices=[...distractors];choices.splice(answer,0,correct);
 bank.push({id:`c13-q${String(index+1).padStart(3,'0')}`,section,kind,prompt,choices,answer,explanation,why:explanation,source,...(termId?{termId,term:termId}:{})});
}
const tq=(id,prompt,correct,wrong,why,source)=>add(TERMS.find(t=>t.id===id).section,'term',prompt,correct,wrong,why,source,id);
const q=(section,prompt,correct,wrong,why,source)=>add(section,'topic',prompt,correct,wrong,why,source);

tq('second-great-awakening','Which term names the evangelical revival movement that helped inspire antebellum reform?','Second Great Awakening',["First Great Awakening","transcendentalism","millennialism"],'The Second Great Awakening stressed conversion and personal salvation and helped energize efforts to reform society.',['P003','P004']);
tq('second-great-awakening','An outdoor revival invites individuals to reject a sinful past and be born again. Which movement best fits?','Second Great Awakening',["Transcendentalism","Shaker communalism","Mormon migration"],'Emotional conversion and the possibility of changing one’s spiritual life were central to the revival.',['P003']);
tq('millennialism','Which term means belief in a thousand-year reign of God on earth?','millennialism',["predestination","transcendentalism","pietism"],'Millennialism anticipated a divine earthly kingdom marked by harmony and Christian morality.',['P004']);
tq('millennialism','A reformer expects a future earthly kingdom of Christian harmony lasting one thousand years. Which belief is this?','millennialism',["pietism","predestination","transcendentalism"],'The thousand-year divine reign is the identifying feature of millennialism.',['P004']);
tq('transcendentalism','Which movement emphasized intuition, individual insight and spiritual meaning in nature?','transcendentalism',["revivalism","pietism","Fourierism"],'Transcendentalists sought insight beyond ordinary sensory experience and resisted social conformity.',['P009','P010']);
tq('transcendentalism','A writer urges readers to trust their own judgment rather than conform to the majority. Which term best fits?','transcendentalism',["pietism","revivalism","Fourierism"],'Emerson’s emphasis on independent judgment reflects transcendentalism’s defense of individual insight.',['P009','P010']);
tq('pietistic','Which word describes a religious emphasis on personal spiritual transformation over formal ritual?','pietistic',["millennial","predestinarian","transcendentalist"],'The German Protestant societies described in the reading valued personal piety and transforming religious experience.',['P018']);
tq('pietistic','A religious community gives inward piety more weight than ceremony. How does the chapter describe this approach?','pietistic',["millennial","secular","transcendentalist"],'Pietistic communities stressed an individual’s religious experience rather than ritual formality.',['P018']);
tq('shakers','Which group practiced shared property and held men and women as equals in religious communities?','Shakers',["Mormons","Owenites","Fourierists"],'The Shakers combined a religious mission with communal property, gender equality and self-sufficiency.',['P019']);
tq('shakers','A self-sufficient religious community shares material goods and makes carefully crafted furniture. Which group fits?','Shakers',["Owen's New Harmony community","Brook Farm transcendentalists","Fourierist associations"],'The chapter uses Shaker workmanship, shared property and communal self-sufficiency as distinctive examples.',['P019']);
tq('mormons','Which group was founded by Joseph Smith and later led west by Brigham Young?','Mormons',["Shakers","Brook Farm transcendentalists","Owenites"],'Smith organized the religious movement in 1830; Young led it toward the Salt Lake region after Smith’s death.',['P020','P021']);
tq('mormons','The Book of Mormon and a migration under Brigham Young are associated with which group?','Mormons',["Shakers","Brook Farm transcendentalists","Fourierists"],'The Book of Mormon was published in 1830, and Brigham Young later led the community west.',['P020','P021']);
tq('temperance','Which term means moderation or self-restraint, especially regarding alcohol?','temperance',["teetotalism","prohibition","moral suasion"],'Early temperance advocates urged restrained drinking; complete abstinence became a later, stronger demand.',['P027','P029']);
tq('temperance','An early reform society asks members to drink moderately rather than stop every kind of alcohol. Which term fits?','temperance',["teetotalism","prohibition","moral suasion"],'Temperance originally allowed moderation, while teetotalism required no alcohol at all.',['P027','P029']);
tq('teetotalism','Which term specifically means giving up all alcohol?','teetotalism',["temperance as early moderation","legal prohibition","moral suasion"],'Teetotalism meant total abstinence, extending the restriction to beer and wine as well as spirits.',['P029']);
tq('teetotalism','A pledge rejects beer, wine and hard liquor. What does this pledge require?','teetotalism',["Moderation in alcohol use","Abstinence from distilled spirits alone","Legal prohibition of alcohol sales"],'Refusing every alcoholic drink is the defining requirement of teetotalism.',['P029','P031']);
tq('phrenology','Which discredited practice claimed skull shape revealed mental traits?','Phrenology',['Transcendentalism','Moral suasion','Millennialism'],'Phrenology tried to infer character from the cranium. Its skull-reading claims are pseudoscience.',['P035','P036']);
tq('phrenology','A traveling lecturer claims to identify a person’s abilities by examining bumps on the head. What is this?','Phrenology',["Transcendentalism","Pietism","Moral suasion"],'Such demonstrations helped popularize phrenology, whose claims about skull contours were not valid science.',['P035','P036']);
tq('colonization','In the chapter’s slavery debate, what term describes relocating African Americans outside the United States?','colonization',["immediatism","gradual emancipation","political abolitionism"],'Colonization proposed relocation, usually to Africa, rather than a multiracial society of equals in the United States.',['P039','P040']);
tq('colonization','The ACS supports Black relocation to Liberia. Which approach is this?','colonization',["Moral suasion for equality in the United States","Immediate emancipation without relocation","Political abolitionism through elections"],'The American Colonization Society supported removal to Africa; abolitionists criticized the racist assumptions behind this approach.',['P039','P040','P047']);
tq('abolitionist','Which term identifies a person who works to end slavery?','abolitionist',["colonization advocate","temperance reformer","communal reformer"],'Abolitionists sought slavery’s elimination; the chapter highlights demands for immediate abolition and equal rights.',['P044','P045']);
tq('abolitionist','An activist publishes antislavery tracts and organizes petitions demanding slavery’s end. Which term describes the activist?','abolitionist',["Colonization advocate","Temperance organizer","Religious tract missionary"],'These actions belong to the abolitionist movement. Other reform identities do not necessarily imply opposition to slavery.',['P045','P048']);
tq('moral-suasion','What term names abolitionists’ appeals to people’s consciences?','moral suasion',["colonization","immediatism","political abolitionism"],'Moral suasion used persuasive accounts of slavery’s injustice to change public opinion.',['P047']);
tq('moral-suasion','A speaker describes the sale of children away from parents to persuade listeners that slavery is wrong. What method is this?','moral suasion',["Armed resistance","Colonization","Electoral campaigning"],'The speaker appeals to conscience through evidence of slavery’s harms, a central strategy of moral suasion.',['P047','P050']);
tq('immediatism','Which term means the demand for immediate action to end slavery?','immediatism',["moral suasion","gradual emancipation","colonization"],'Garrison’s immediatism rejected postponement and demanded immediate action against slavery.',['P048']);
tq('immediatism','A reformer rejects an indefinite timetable for emancipation and insists that slavery must end now. Which position is this?','immediatism',["Colonization","Moral suasion","Gradualism"],'Immediatism states the urgency of abolition; it does not prescribe a single tactic such as violence.',['P048']);
tq('seneca-falls','Which place hosted the 1848 women’s rights convention associated with the Declaration of Sentiments?','Seneca Falls',["London","Rochester","Boston"],'Seneca Falls, New York, hosted the convention organized by Stanton and Mott.',['P059']);
tq('seneca-falls','A convention associated with Stanton and Mott applies the language of equal rights to women. Which bold term identifies it?','Seneca Falls',["World Anti-Slavery Convention","Washington Temperance Society","Brook Farm"],'The 1848 Seneca Falls Convention asserted women’s equality through the Declaration of Sentiments.',['P057','P059']);

// 13.1 — sixteen topic questions.
q('13.1','How did the Second Great Awakening’s message differ from strict Calvinist predestination?','It emphasized individuals’ ability to seek conversion and salvation.',['It made salvation depend chiefly on membership in a cooperative community.','It preserved the view that an individual’s spiritual destiny was fixed before birth.','It replaced personal conversion with improvement through educated reason.'],'Revivalists emphasized personal conversion, challenging the idea that salvation was reserved for a predetermined few.',['P003']);
q('13.1','Why could revival religion appeal to Americans experiencing rapid social and economic change?','It offered moral stability and a sense of personal agency.',['It made shared property the main remedy for industrial competition.','It promised spiritual insight chiefly through solitude and nature.','It made the reorganization of factory work the basis of religious salvation.'],'Population growth, western expansion and democratization created anxiety; revival offered comfort and the possibility of self-directed change.',['P004']);
q('13.1','Which pair correctly distinguishes the two Great Awakenings discussed in the reading?','First: 1730s–1740s; Second: later revival tied to antebellum reform.',["First: early republic; Second: colonial revivals in the 1730s–1740s.","First: 1730s–1740s; Second: post–Civil War temperance crusades.","First: years after the War of 1812; Second: the 1848 convention era."],'The chapter places the first evangelical awakening in the colonial 1730s–1740s and the second in the early republic.',['P003','P004']);
q('13.1','What did a circuit rider do?','Travel as a minister without a fixed congregation.',["Serve as a minister assigned to a settled parish for a long term.","Distribute Bibles and tracts without conducting revival preaching.","Lead a communal religious settlement and direct its shared labor."],'Circuit riders and missionaries spread revival preaching across the country.',['P006']);
q('13.1','Which organization focused on religious education for children?','American Sunday School Union.',["American Bible Society.","American Tract Society.","American Temperance Society."],'Founded in 1824, the American Sunday School Union published and organized religious instruction for young readers.',['P005']);
q('13.1','What did the American Bible Society and American Tract Society have in common?','They used printed material to spread Protestant religious messages.',['They used publications to advocate immediate emancipation from slavery.','They organized practical training for communities based on shared property.','They used pledge campaigns to promote total abstinence from alcohol.'],'Bible distribution and religious tracts helped revival beliefs reach families beyond individual meetings.',['P005']);
q('13.1','Why had some enslavers feared enslaved people’s conversion to Christianity?','They feared Christian ideas could support arguments against enslavement.',["They believed state law made baptism and manumission the same legal act.","They thought revival religion required converts to join communal settlements.","They believed Christian teaching required converts to withdraw from productive labor."],'Some enslavers worried that Christian principles could be used to challenge slavery; conversion did not automatically bring freedom.',['P006']);
q('13.1','Who became a leading revival preacher in Rochester, New York, in 1830?','Charles Grandison Finney.',["Lyman Beecher.","Joseph Smith.","George Ripley."],'Finney brought evangelical revival preaching to the growing canal city of Rochester.',['P007']);
q('13.1','Why is Rochester’s Erie Canal growth relevant to Finney’s revival?','It shows revival religion flourishing amid market-driven social change.',['It shows revival religion declining as canal towns attracted more merchants.','It places the revival before the growth of transportation and market exchange.','It identifies the revival chiefly with people seeking escape from urban life.'],'Rochester’s shipping boom made it an example of economic transformation alongside religious revival.',['P007','P008']);
q('13.1','What did western New York’s nickname “burned-over district” describe?','Repeated waves of intense religious enthusiasm.',["Industrial fires spreading through the growing towns along the Erie Canal.","The decline of older churches as western New York became less religious.","Government destruction of settlements founded by new religious movements."],'The phrase referred to revival fervor sweeping the region, rather than a literal burn zone.',['P008']);
q('13.1','Why did many middle-class people welcome Finney’s message?','Personal control over salvation fit their belief in shaping their own destinies.',["Religious status depended more on loyalty to a fixed church hierarchy than on individual effort.","Salvation required withdrawing from the market economy into communal life.","A person's economic success was itself a guarantee of salvation."],'Finney’s emphasis on personal agency resonated with the self-improvement outlook of the emerging middle class.',['P008']);
q('13.1','How did European romanticism influence American transcendentalists?','It emphasized emotion and individual feeling over purely calculating reason.',["It treated empirical measurement as the main route to spiritual knowledge.","It placed inherited religious authority above the individual's feelings.","It emphasized social harmony through rationally planned communal production."],'Romanticism’s attention to emotion and the individual helped shape transcendentalist criticism of conformity.',['P009','P010']);
q('13.1','What is the central connection between Emerson’s Nature and his spiritual outlook?','Nature can offer a path to spiritual understanding.',['Spiritual truth depends primarily on the authority of established churches.','Shared property is necessary before individuals can gain spiritual insight.','Rational organization of factory labor is the main source of moral knowledge.'],'Emerson’s 1836 essay directed readers toward nature rather than the bustle of industrial life as a source of spirituality.',['P010']);
q('13.1','What did Emerson urge in Self-Reliance?','Think independently rather than surrender judgment to conformity.',["Judge belief chiefly by established religious authority.","Seek fulfillment through shared property and planned collective labor.","Accept social customs as a more reliable guide than personal insight."],'Self-Reliance, published in 1841, challenged conformity and encouraged independent thought.',['P010']);
q('13.1','What injustices helped motivate Thoreau’s argument that individuals should resist government wrongdoing?','Slavery and the Mexican-American War.',['Temperance campaigns and disputes over the sale of hard liquor.','Industrial competition and the rejection of cooperative factory reform.','Restrictions on women’s public lecturing and their exclusion in London.'],'Thoreau connected individual conscience to criticism of slavery and the war with Mexico.',['P012']);
q('13.1','How does the chapter use Melville’s Captain Ahab to complicate praise of individualism?','Ahab’s destructive obsession shows that individual will can become dangerous.',['Ahab’s pursuit of his goal shows individual judgment reliably correcting social injustice.','Ahab’s refusal to follow custom makes him a model of Emerson’s self-reliance.','Ahab’s conflict makes majority opinion, rather than individual obsession, the source of danger.'],'Melville’s story and Poe’s criticism illustrate a debate over individualism’s limits, rather than unanimous support for transcendentalism.',['P013']);

// 13.2 — twelve topic questions.
q('13.2','What broad change helped inspire experiments in communal living after 1815?','The expanding market economy disrupted older patterns of family production.',["A revival of household production reduced families' dependence on markets and employers.","A decline in factory work encouraged reformers to recreate industrial employment in communes.","The weakening of revival religion made secular experiments replace religious communities."],'Market and industrial changes encouraged some reformers to seek alternatives based on cooperation and harmony.',['P015','P016']);
q('13.2','When did the communal experiment movement reach its high point, according to the chapter?','The 1840s.',["The 1820s.","The 1830s.","The 1850s."],'Many short-lived experimental communities appeared, with the movement reaching its apex in the 1840s.',['P016']);
q('13.2','Which goal united many different utopian communities?','Creating a more equal and harmonious way of living.',["Helping individual households succeed through private ownership and market competition.","Winning political office before changing the organization of daily work.","Standardizing religious belief while preserving conventional property arrangements."],'Although their beliefs differed, many communal reformers hoped to improve human relationships through alternative arrangements.',['P016']);
q('13.2','Which statement best describes the sources of communal reform?','Some communities were religious, while others drew on secular or intellectual ideas.',["Secular communities developed first, and revival religion entered communal reform only later.","Religious communities relied on personal faith, while secular communities rejected shared labor.","The experiments grew chiefly from one evangelical model, with differences mainly in location."],'Revival religion inspired many groups, but Brook Farm, Owen and Fourier also reflected other intellectual approaches.',['P017','P022','P023','P024']);
q('13.2','What was distinctive about gender and property in Shaker communities?','Women and men were treated as equals, and material goods were held communally.',['Women and men held separate private property while sharing religious services.','Men directed communal labor while women lacked equal spiritual standing.','Each family competed for wages and owned its productive property separately.'],'The chapter presents Shaker equality and shared goods as radical departures from conventional society.',['P019']);
q('13.2','Which event correctly belongs to Joseph Smith’s role in the Mormon movement?','Publishing the Book of Mormon and organizing a church in 1830.',['Leading the main migration to the Salt Lake region and establishing its settlement.','Organizing the original Shaker communities around shared property and celibacy.','Founding Brook Farm as an experiment combining religious conversion and manual labor.'],'Smith was the founding prophet of the movement; Brigham Young assumed leadership after Smith was killed.',['P020','P021']);
q('13.2','What is the correct sequence in the Mormon history described in the chapter?','Smith organizes the movement; Smith is killed; Young leads followers west.',['Young organizes the church; Smith leads the migration; the community settles near Salt Lake.','Smith organizes the church; Young leads followers west; Smith is killed after the Salt Lake settlement.','Smith leads followers to Salt Lake; the church is organized; Young takes over after Smith’s death.'],'The sequence distinguishes founding leadership from the later westward migration under Brigham Young.',['P020','P021']);
q('13.2','Who founded Brook Farm, and what did its community combine?','George Ripley; manual labor and intellectual pursuits.',['Robert Owen; factory reform and secular cooperative living.','Ann Lee; communal property and a religious rule of life.','Charles Fourier; wage incentives and organized cooperative associations.'],'Ripley’s Massachusetts community drew transcendentalist thinkers into an experiment joining practical labor with intellectual life.',['P022']);
q('13.2','What intellectual connection makes Brook Farm different from a purely evangelical community?','Its founding was associated with transcendentalism.',["Its community followed Owen's secular program for industrial workers.","Its founding rested on Joseph Smith's teachings and religious migration.","It treated millennial prophecy as the basis of its division of labor."],'George Ripley was a transcendentalist, and Brook Farm attracted individualistic writers and thinkers.',['P022']);
q('13.2','What inspired Robert Owen’s cooperative vision?','Faith in human reason and concern about industrial workers’ conditions.',['Personal conversion and preparation for a thousand-year divine kingdom.','Individual intuition and spiritual insight gained through contact with nature.','Inward religious piety rather than the organization of industrial work.'],'The industrialist Owen used his experience of factory work to promote cooperative societies, drawing on reason rather than religious inspiration.',['P023']);
q('13.2','Which arrangement is associated with Charles Fourier?','Cooperative associations living in large communal buildings called phalanxes.',["Religious settlements holding property in common and requiring celibacy.","Factory communities formed around Owen's secular faith in human reason.","Voluntary settlements combining farm work with transcendentalist writing and discussion."],'Fourier advocated collective associations and communal living arrangements, promoted in the United States through publications and lectures.',['P024']);
q('13.2','How did Fourierists propose compensating especially unpleasant work?','Pay higher wages for the less appealing jobs.',["Pay every member the same wage regardless of the task.","Pay workers chiefly according to the private property they brought into the association.","Use an equal rotation of unpleasant jobs instead of higher wages."],'Fourierists treated labor as capital and argued that more unpleasant jobs deserved higher pay.',['P024']);

// 13.3 — sixteen topic questions.
q('13.3','Why did many antebellum reformers regard heavy drinking as a public problem?','They connected it to damaged families, morality and civic life.',["They regarded drinking chiefly as a medical issue for physicians rather than civic reform groups.","They treated drinking chiefly as a dispute about tavern licensing rather than family welfare.","They regarded it as a private failing whose remedy did not require public reform."],'The chapter links alcohol reform to concerns about household welfare, Christianity, work and democracy.',['P026','P031']);
q('13.3','What did the earliest New England temperance societies generally seek?','More restrained drinking rather than the elimination of every drink.',['Total abstinence from spirits, beer and wine through a public pledge.','A statewide prohibition on the manufacture and sale of alcoholic drinks.','State control of liquor purchases through minimum-quantity requirements.'],'Early societies emphasized piety and moderation; the movement’s demands later became more restrictive.',['P027']);
q('13.3','What role did Lyman Beecher play in alcohol reform?','He preached widely read temperance sermons and encouraged voluntary associations.',["He founded the working-class Washingtonians and organized public recovery pledges.","He wrote Massachusetts's minimum-quantity liquor law as a state legislator.","He secured the first statewide prohibition statute through a campaign in Maine."],'Beecher’s sermons helped popularize abstinence from hard liquor and organized temperance activity.',['P028']);
q('13.3','Why did temperance appeal to the emerging middle class?','It fit an ethic of hard work and a sober workforce.',["It sought to replace wage work with communal ownership of factories.","It linked self-improvement chiefly to spiritual withdrawal from commercial life.","It sought legal protection for moderate drinking as part of workplace custom."],'Middle-class reformers linked sobriety to moral improvement and disciplined labor.',['P028']);
q('13.3','How did many temperance societies change their pledge by 1836?','They expanded it from avoiding hard liquor to avoiding all alcohol.',['They narrowed abstinence pledges to distilled spirits while permitting beer and wine.','They replaced personal pledges with support for statewide legal prohibition.','They shifted from abstinence to promises of moderate social drinking.'],'The shift to teetotalism included beer and wine, creating a stricter standard and some internal disagreement.',['P029','P030']);
q('13.3','What immediate difficulty followed the movement’s stronger demand for total abstinence?','Disagreement and a loss of momentum after 1836.',["Statewide legal prohibition displaced voluntary societies as soon as the pledge changed.","The movement adopted hard-liquor moderation in place of total abstinence as its agreed policy.","Working-class Washingtonian leadership took over the movement in 1836."],'The stricter teetotal position divided some supporters before a new revival of the cause in the 1840s.',['P030']);
q('13.3','What distinguished the Washington Temperance Society from many earlier societies?','Working-class leaders directed efforts toward people already struggling with alcohol.',['Protestant ministers led preventive campaigns among the sober middle class.','State legislators directed efforts toward criminal penalties for liquor sellers.','Employers organized reform chiefly to create a more disciplined factory workforce.'],'The Washingtonians, organized in 1840, used a working-class approach rather than relying primarily on Protestant ministers and middle-class audiences.',['P030']);
q('13.3','Why did Washingtonians welcome women and children?','Alcohol abuse directly affected household finances and family safety.',['They considered women’s participation mainly a way to secure equal voting rights.','They treated family membership as a substitute for a person’s abstinence pledge.','They focused on children’s religious schooling rather than the effects of drinking.'],'Women and children experienced the financial, physical and emotional harms caused by alcohol abuse in households.',['P031']);
q('13.3','How did the Washingtonians make their message emotionally powerful?','They dramatized the suffering caused by drunkenness and used public pledges.',['They emphasized sermons on doctrine delivered mainly by ordained ministers.','They emphasized legal penalties for sellers rather than personal experiences of drinking.','They emphasized efficiency in factory work rather than the harm suffered by families.'],'Theatrical narratives and public commitments helped the Washingtonian movement attract large numbers of supporters.',['P031']);
q('13.3','What was the purpose of Massachusetts’s 1838 minimum-quantity liquor law?','Make spirits harder for people of modest means to buy in small amounts.',['Prevent the sale of all alcoholic drinks through a statewide prohibition.','Require local governments to decide whether their own towns would remain dry.','Encourage buyers to sign voluntary pledges instead of regulating liquor sales.'],'The law restricted sales below fifteen gallons; it was a state measure, not a national ban.',['P032']);
q('13.3','What happened after Massachusetts repealed its 1838 liquor law?','Some towns used local bans, and many became dry.',['Statewide prohibition replaced the minimum-quantity law without relying on town decisions.','The state returned to voluntary abstinence pledges and local restrictions declined.','The minimum-quantity rule remained binding on towns despite repeal at the state level.'],'Repeal in 1840 did not end reform: local governments continued restrictions, with many towns dry by 1845.',['P032']);
q('13.3','What does the chapter’s example of Mississippi’s 1839 liquor law show?','Temperance had supporters in both northern and southern states.',["Southern temperance remained a voluntary campaign, leaving liquor regulation to northern states.","Southern states adopted liquor restrictions only after Maine's 1851 law.","Minimum-quantity restrictions meant Mississippi had already enacted statewide prohibition."],'Although northern states pushed hardest for prohibition, the Mississippi example shows the cause crossed regional boundaries.',['P033']);
q('13.3','Which state enacted the first statewide prohibition law in 1851?','Maine.',["Massachusetts.","New York.","Ohio."],'Maine’s 1851 law is a key milestone in the movement from voluntary reform toward legal prohibition.',['P033']);
q('13.3','The reading also discusses women’s temperance crusades beginning in 1873. How should they fit the timeline?','They are a later continuation of reform, after the antebellum era.',["They represent the first stage of temperance, before total abstinence became a goal.","They launched women's participation in reform rather than continuing earlier organizing.","They show women entering reform after alcohol prohibition had already become national law."],'The chapter includes later developments, but 1873 comes after both the antebellum period and the Civil War.',['P034']);
q('13.3','Who first developed the phrenological ideas discussed in the chapter?','Franz Joseph Gall.',["Ralph Waldo Emerson.","Robert Owen.","Charles Fourier."],'Gall’s European ideas reached the United States in the 1820s and became popular through lecturers and demonstrations.',['P036']);
q('13.3','Which judgment best distinguishes historical phrenology from modern scientific knowledge?','Its skull-reading claims were false even though it raised questions about brain functions.',["Its account of character was reliable, although its claims about specialized brain functions were mistaken.","Its early use in education supplied scientific proof that skull shape could predict ability.","Its main error was relying on individual intuition instead of using physical measurements."],'The reading explicitly identifies phrenology as pseudoscience. Historical popularity and interest in brain specialization do not validate character-reading from the skull.',['P035','P036']);

// 13.4 — twenty topic questions.
q('13.4','What is the central difference between ACS colonization and the abolitionism emphasized in the chapter?','Relocation out of the country versus ending slavery and pursuing equality within it.',['Gradual emancipation within the United States versus relocation to Liberia.','Political campaigning versus avoiding elections in favor of moral persuasion.','Equal rights for free Black people versus limiting reform to enslaved people.'],'The ACS assumed Black and White people could not live as equals; abolitionists such as Garrison rejected that premise.',['P038','P039','P040','P044']);
q('13.4','Which destination was closely associated with the American Colonization Society?','Liberia, with its capital Monrovia.',["Sierra Leone, centered on Freetown.","Haiti, in the Caribbean.","British colonies in the Caribbean."],'The ACS helped establish Liberia in West Africa; Monrovia was named for President James Monroe.',['P040']);
q('13.4','Why did abolitionists criticize colonization?','It rested on racist assumptions and displaced Black people rather than establishing equality.',['It relied on armed revolt rather than persuasive appeals to conscience.','It placed electoral campaigns ahead of direct moral appeals against slavery.','It sought gradual emancipation while requiring Black families to remain in the South.'],'Garrison came to reject colonization because he believed it perpetuated racism instead of confronting slavery and inequality.',['P040','P045','P047']);
q('13.4','What did the ACS’s focus on free Black people reveal?','Its relocation project was not simply a plan for immediate emancipation of all enslaved people.',["Its main effort was to secure immediate emancipation for people still held in slavery.","It sought civil and political equality for free Black people within the United States.","It planned to keep free Black communities at home while moving newly emancipated people abroad."],'The chapter says the ACS targeted free Black Americans for relocation, reflecting opposition to a multiracial society of equals.',['P040']);
q('13.4','Where and when did Nat Turner’s Rebellion occur?','Southampton County, Virginia, in 1831.',["Southampton County, Virginia, in 1841.","Richmond, Virginia, in 1831.","Charleston, South Carolina, in 1831."],'Turner’s uprising in Virginia was a major enslaved revolt, distinct from northern reform conventions and ACS colonization.',['P041']);
q('13.4','How did Nat Turner’s religious experience connect to the wider era?','Evangelical revival fervor influenced his preaching and understanding of rebellion.',['He adopted Owen’s belief that human reason would produce a harmonious cooperative society.','He relied on Garrison’s moral-suasion strategy to persuade enslavers through peaceful appeals.','He based his mission chiefly on transcendentalist intuition rather than evangelical preaching.'],'The same revival era shaped sharply different actions: Turner understood his mission through religious belief.',['P041']);
q('13.4','What was a major political consequence of Turner’s Rebellion?','Virginia and other slave states recommitted to slavery and repression.',["Virginia eased restrictions on manumission to encourage gradual emancipation.","Southern legislatures adopted colonization as the replacement for slavery.","Virginia's antislavery debate produced a gradual emancipation law."],'The rebellion closed off discussion of easier manumission in Virginia and intensified defenders’ commitment to slavery.',['P043']);
q('13.4','Which statement best distinguishes Turner’s revolt from Garrison’s preferred method?','Turner used armed rebellion; Garrison emphasized nonviolent appeals to conscience.',["Turner sought gradual emancipation through state law; Garrison sought immediate emancipation through Congress.","Turner urged relocation abroad; Garrison urged enslaved people to rebel.","Turner relied on mass religious conversion; Garrison relied on a national political party."],'The chapter presents violent revolt and Garrisonian moral suasion as different approaches; accusations against Garrison were not proof he organized the uprising.',['P041','P046','P047']);
q('13.4','Which newspaper did William Lloyd Garrison found in 1831?','The Liberator.',["North Star.","Freedom's Journal.","The New-York Tribune."],'The Liberator became a prominent abolitionist newspaper. North Star was Frederick Douglass’s later newspaper.',['P045','P050']);
q('13.4','How did Garrison’s position change over time?','He moved from supporting colonization to condemning it and demanding abolition.',['He moved from moral suasion to running abolitionist candidates for office.','He moved from immediate emancipation to a gradual plan tied to relocation.','He moved from publishing antislavery arguments to relying mainly on armed resistance.'],'Garrison rejected the racist implications of colonization and pursued immediate abolition and equality.',['P045','P047','P048']);
q('13.4','Which organization did Garrison help found in 1833?','American Anti-Slavery Society.',["American Colonization Society.","American Bible Society.","Liberty Party."],'The AASS organized abolitionism and used lectures, publications and persuasion to challenge slavery.',['P047']);
q('13.4','How were personal narratives useful to abolitionist moral suasion?','They exposed slavery’s concrete harms, including the separation of families.',['They offered a timetable for gradual emancipation negotiated with enslavers.','They described relocation to Liberia as the best route to equality.','They made electoral organization more important than appeals to conscience.'],'Accounts from formerly enslaved people made the injustice of slavery vivid and challenged the public’s conscience.',['P047','P050']);
q('13.4','Why could petitions to Congress spread abolitionist arguments beyond their original signers?','Newspapers printed congressional proceedings and brought the debate to more readers.',["Congress was required to hold a recorded vote on emancipation each time it received a petition.","Petitions persuaded legislators mainly through private meetings, with little wider circulation.","A petition's signatures were treated as binding instructions to congressional representatives."],'Petitions generated public discussion even without immediate legislative victory.',['P048']);
q('13.4','How did the Liberty Party differ from Garrison’s approach to the political system?','It sought abolition through mainstream electoral politics.',['It sought abolition by withdrawing from elections and appealing to conscience.','It made the relocation of free Black people to Liberia its central goal.','It relied on organizing armed revolts within the slave states.'],'Garrison distrusted the political system as serving slaveholders; other abolitionists formed the Liberty Party in 1840.',['P049']);
q('13.4','Who was the Liberty Party’s first presidential candidate in 1840?','James G. Birney.',["William Lloyd Garrison.","Frederick Douglass.","Charles Grandison Finney."],'Birney, a former enslaver who rejected colonization and embraced emancipation, ran as the party’s first presidential candidate.',['P049']);
q('13.4','Which statement correctly pairs Frederick Douglass with his work?','He escaped slavery, published an autobiography in 1845 and later published North Star.',["He established The Liberator in 1831 and helped found the AASS in 1833.","He founded the Liberty Party and became its first presidential candidate in 1840.","He advocated colonization after publishing an account of his life under slavery."],'Douglass combined lived testimony, public speaking and journalism to expose slavery and argue for its end.',['P050']);
q('13.4','Why is describing abolition as only a White-led movement incomplete?','Black activists organized and led reform efforts even when national groups excluded them from leadership.',['Black activists mainly supplied testimony while White organizations provided the movement’s leadership.','Black leaders concentrated on colonization while White leaders favored immediate emancipation.','Black participation became an organized force after emancipation rather than during the antebellum period.'],'The reading highlights Black organizing, Douglass’s leadership and exclusion that forced some activists to form their own organizations.',['P050','P052']);
q('13.4','What public action by the Grimké sisters challenged gender conventions?','Lecturing on abolition to audiences that included both women and men.',['Organizing temperance pledges for women and children in family-centered meetings.','Supporting women’s reform work while reserving public addresses to men.','Speaking about abolition only within women’s private religious gatherings.'],'Their 1837 speaking tour exposed objections to women addressing men and intensified debate over women’s public roles.',['P053','P054']);
q('13.4','How did the Grimké sisters’ backgrounds sharpen their reform message?','They came from a South Carolina slaveholding family and later opposed slavery.',["They grew up in northern factory towns and approached abolition through industrial labor reform.","They began as colonization advocates and supported women's reform chiefly within the home.","They were raised in western communal settlements and built their activism around shared property."],'Their move north, Quaker conversion and abolitionist work joined opposition to slavery with advocacy of women’s equality.',['P053']);
q('13.4','What does disagreement over the Grimké sisters reveal about abolitionist organizations?','A shared antislavery goal did not mean agreement about women’s public roles.',["Disputes concerned electoral tactics rather than women's right to address mixed audiences.","Garrison opposed the sisters' public lectures while their critics defended an equal speaking role.","The movement treated women's speaking roles as settled and shifted the controversy to property ownership."],'Garrison supported their lectures, while other abolitionists objected, revealing divisions within the reform movement.',['P051','P054']);

// 13.5 — eight topic questions.
q('13.5','Which reform activity especially helped launch the organized women’s rights movement?','Participation in abolitionist organizing and challenges to women’s exclusion.',['A transition from temperance societies directly into a national suffrage party.','Participation in religious communal experiments that already granted women equal political rights.','Support for colonization as a way to resolve racial and gender inequality together.'],'Antislavery organizing gave women practical experience and prompted them to examine gender inequality.',['P056','P057']);
q('13.5','How did women’s participation in temperance initially fit conventional expectations?','It drew on their accepted role as moral guardians of home and family.',['It placed women in formal leadership over the churches sponsoring reform.','It treated women as independent wage earners with the same legal rights as men.','It made gaining political office the first step toward reforming family life.'],'Some reform work extended accepted ideas of women as nurturers, while other activism challenged those limits.',['P056']);
q('13.5','Which pair met at the 1840 World Anti-Slavery Convention in London and later organized for women’s rights?','Lucretia Mott and Elizabeth Cady Stanton.',["Sarah and Angelina Grimké.","Lucy Stone and Susan B. Anthony.","Lydia Maria Child and Angelina Grimké."],'Mott and Stanton’s connection in the antislavery movement helped lead toward the 1848 women’s rights convention.',['P057']);
q('13.5','Which sequence is correct?','London antislavery convention in 1840, then Seneca Falls in 1848.',["Seneca Falls in 1840, then the London antislavery convention in 1848.","The London antislavery convention in 1833, then Seneca Falls in 1848.","The London antislavery convention in 1848, then Seneca Falls in 1851."],'Eight years separated the 1840 London convention from the 1848 Seneca Falls meeting.',['P057','P059']);
q('13.5','What founding document supplied a model for the Declaration of Sentiments?','The Declaration of Independence.',["The United States Constitution.","The Bill of Rights.","The Articles of Confederation."],'The declaration adapted the language of natural rights and equality to argue for women’s rights.',['P059']);
q('13.5','What was the significance of including women in the Declaration of Sentiments’ equality claim?','It challenged the exclusion of women from the nation’s professed rights.',["It treated equality as a religious ideal while leaving women's civil status outside the declaration.","It grounded women's rights in their household role rather than a claim of natural equality.","It presented voting rights as already secured and concentrated on workplace reform."],'The convention used familiar equality language to expose the gap between national ideals and women’s treatment.',['P059']);
q('13.5','Who attended the Seneca Falls Convention?','About three hundred women and men, many with abolitionist experience.',['An all-women gathering that excluded male abolitionists from the proceedings.','A national assembly of elected delegates representing the major political parties.','A meeting made up chiefly of ministers directing an evangelical revival.'],'The convention included both women and men and drew heavily on the networks of antislavery reform.',['P059']);
q('13.5','Which conclusion best connects the chapter’s reform movements?','Efforts to improve society expanded activism while exposing limits in equality and inclusion.',["Reform followed a single evangelical program, with differences mainly in the organizations carrying it out.","Reformers generally agreed on equality but disagreed chiefly over which publication to use.","Secular reform mainly replaced religious reform, rather than developing alongside it."],'Revival, communal experiments, temperance, abolition and women’s rights shared hopes for improvement but differed in methods and ideas of equality.',['P004','P016','P031','P040','P054','P059']);

// Additional close-reading connections retain the original question IDs above.
q('13.1','Which audience and activity helped Emerson’s ideas spread beyond his lectures?','Literate adults seeking spiritual meaning expressed the ideas in stories, poems, essays and articles.',["Ministers spread the ideas mainly by issuing a common doctrine for established churches.","Cooperative organizers spread the ideas chiefly through rules for wages and communal property.","Middle-class readers spread the ideas mainly as arguments for conformity and commercial success."],'Emerson attracted readers dissatisfied with mainstream life. Literary expression helped those readers explore and circulate transcendentalist ideas.',['P011']);
q('13.4','What response to Nat Turner’s Rebellion does the reading describe in addition to Turner’s own execution?','Executions of suspected participants and killings by vigilantes and militias during a broader panic.',['Virginia’s legislature approved a broad emancipation program in response to the uprising.','The authorities confined punishment to those convicted, while local militias restrained reprisals.','Public debate centered on compensation for enslavers, with little violence beyond the initial revolt.'],'The reading distinguishes state executions from further killings by vigilantes and militias. The violence and panic reached beyond the initial attack; the question does not treat disputed death estimates as an exact count.',['P042']);
q('13.5','What does feminism mean in the chapter’s discussion of women reformers?','Advocacy of women’s rights.',['The pursuit of household reform without challenging women’s legal or political position.','Equal spiritual standing within a religious community rather than broader civil rights.','The demand for a total ban on alcohol as the foundation of family reform.'],'The chapter connects women’s antislavery experience to feminism: challenging gender inequality and advocating women’s rights. It identifies Child, Stanton, Stone and Anthony among women sharing those concerns.',['P058']);
q('13.5','Why did Lydia Maria Child draw a comparison between women’s subordination and the oppression of Black people?','To connect challenges to unequal power with the case for both abolition and women’s rights.',["To argue that ending slavery would itself resolve women's legal inequalities.","To make women's domestic influence, rather than equal rights, the foundation of reform.","To treat racial and gender subordination as separate problems requiring different movements."],'Child highlighted subjection enforced through power. The comparison helped connect reform causes; it did not mean that women’s and Black people’s experiences were identical.',['P058']);

export const QUESTIONS=bank;
export const BY_ID=new Map(QUESTIONS.map(x=>[x.id,x]));
export const TERM_BY_ID=new Map(TERMS.map(x=>[x.id,x]));
for(const term of TERMS){term.questionIds=QUESTIONS.filter(q=>q.termId===term.id).map(q=>q.id);term.questionId=term.questionIds[0];}
